                    _hide_junction(link_path)
                    return
            except Exception:
                pass
            try:
                link_path.unlink()
            except Exception:
                return
        elif link_path.exists():
            if link_path.is_dir():
                try:
                    already_correct = link_path.resolve() == real_dir_resolved
                except Exception:
                    already_correct = False
